162	        ApiResult updated = updateTerms(docId, 1,
163	                "[{\"sourceTerm\":\"机器学习\",\"language\":\"en\",\"requiredTranslation\":\"ML\"}]",
164	                newRequestId());
165	        assertThat(updated.status()).isEqualTo(201);
166	        assertThat(updated.body().get("termVersion").asInt()).isEqualTo(2);
167	        assertThat(updated.body().get("draftVersion").asInt()).isEqualTo(4);
168	
169	        // 旧译文保留但术语过期：术语状态可见，发布 422
170	        ApiResult status = getJson("/api/documents/" + docId + "/terms/status");
171	        assertThat(status.body().get("termVersion").asInt()).isEqualTo(2);
172	        var entry = status.body().get("translations").get(0);
