                newRequestId());
        assertThat(count.status()).isEqualTo(422);

        // 失败均未覆盖首条成功译文
        assertThat(jdbc.queryForObject(
                "SELECT content FROM translation WHERE document_id = ? AND segment_id = 's1' AND language = 'en'",
